#!/usr/bin/env python3
"""Install The Unframeable Now modules 1–5 into a VS Code workspace.

The script contains the verified source and tests. It makes timestamped backups before
overwriting anything, performs no bundling, and uses only the Python standard library.

Examples:
  python3 unframeable_modules_1_5_install.py --workspace /path/to/the-unframeable-now
  python3 unframeable_modules_1_5_install.py --workspace /path/to/the-unframeable-now --apply --run-tests
"""
from __future__ import annotations

import argparse
import base64
from datetime import datetime, timezone
import hashlib
from pathlib import Path
import shutil
import subprocess
import sys

PAYLOADS = {
    'lab/model.js': '',
    'tests/model.empty-bin.test.js': '',
    'tests/model.moment.test.js': '',
    'tests/model.allostasis.test.js': '',
    'IMPLEMENTATION_LOG.md': '',
}

TESTS = (
    "tests/model.empty-bin.test.js",
    "tests/model.moment.test.js",
    "tests/model.allostasis.test.js",
)


def content(relative: str) -> bytes:
    return base64.b64decode(PAYLOADS[relative].encode("ascii"))


def sha256(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(
        description="Preview or install verified The Unframeable Now modules 1–5."
    )
    parser.add_argument(
        "--workspace", type=Path, default=Path.cwd(),
        help="Target The Unframeable Now workspace (default: current directory).",
    )
    parser.add_argument(
        "--apply", action="store_true",
        help="Write the bundled files. Without this flag the script is a dry run.",
    )
    parser.add_argument(
        "--run-tests", action="store_true",
        help="Run the bundled Node conformance tests after a successful --apply.",
    )
    return parser.parse_args()


def install(workspace: Path) -> Path:
    timestamp = datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%SZ")
    backup_root = workspace / ".unframeable-backups" / timestamp
    for relative in PAYLOADS:
        destination = workspace / relative
        if destination.exists():
            backup = backup_root / relative
            backup.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(destination, backup)
        destination.parent.mkdir(parents=True, exist_ok=True)
        destination.write_bytes(content(relative))
        print(f"written  {relative}  sha256={sha256(content(relative))[:12]}")
    return backup_root


def run_tests(workspace: Path) -> None:
    node = shutil.which("node")
    if not node:
        raise RuntimeError("Node.js was not found; sources were installed but tests were not run.")
    for relative in TESTS:
        print(f"\n> node {relative}")
        subprocess.run([node, relative], cwd=workspace, check=True)


def main() -> int:
    args = parse_args()
    workspace = args.workspace.expanduser().resolve()
    print(f"workspace: {workspace}")
    print("This installer never builds or bundles production assets.")
    if not args.apply:
        print("\nDRY RUN — pass --apply to write these files:")
        for relative in PAYLOADS:
            print(f"  - {relative}  sha256={sha256(content(relative))[:12]}")
        return 0
    workspace.mkdir(parents=True, exist_ok=True)
    backup_root = install(workspace)
    print(f"\nbackup directory: {backup_root}")
    if args.run_tests:
        run_tests(workspace)
    print("\nModules 1–5 installed successfully.")
    return 0


if __name__ == "__main__":
    try:
        raise SystemExit(main())
    except (RuntimeError, subprocess.CalledProcessError) as exc:
        print(f"ERROR: {exc}", file=sys.stderr)
        raise SystemExit(1)
